> +	phy_write_mmd(phydev, MDIO_MMD_VEND1, 0x15, 0x0);
> +
> +	phy_write_mmd(phydev_p0, MDIO_MMD_VEND2, 0x100, 0x0);
> +
> +	return 0;
> +}
