index 530335f002fb..94d67e8bcfbc 100644
--- a/drivers/spi/spi-cadence-quadspi.c
+++ b/drivers/spi/spi-cadence-quadspi.c
@@ -4029,7 +4029,7 @@ static int cqspi_runtime_suspend(struct device *dev)
