>> +		params->shift = 3;
>> +		params->max_raw = 31;
>> +		mult = 1;
>> +		break;
>> +	case 64:
>> +		params->shift = 2;
>> +		params->max_raw = 63;
>> +		mult = 1;
>> +		break;
>> +	case 128:
>> +		params->shift = 1;
>> +		params->max_raw = 127;
>> +		mult = 1;
>> +		break;
>> +	case 256:
>> +		params->shift = 0;
>> +		params->max_raw = 255;
>> +		mult = 1;
>> +		break;
>> +	case 512:
>> +		params->shift = 0;
>> +		params->max_raw = 255;
>> +		mult = 2;
>> +		break;
>> +	case 1024:
>> +		params->shift = 0;
>> +		params->max_raw = 255;
>> +		mult = 4;
>> +		break;
>> +	default:
>> +		return -EINVAL;
>> +	}
> So, this is just a bit twiddling of the dec_rate.
>
> Can be written like
>
> 	/* Optional, perhaps shouldn't appear */
> 	if (!dec_rate)
> 		return -EINVAL;
>
> 	/* Same? What does table allow to have? */
> 	if (!is_power_of_two(dec_rate))
> 		return -EINVAL;
>
> 	mult = ilog2(dec_rate);
> 	if (mult > 10) {
> 		return -EINVAL;
> 	} else if (mult > 8) {
> 		params->shift = 0;
> 		params->max_raw = 255;
> 		mult = BIT(mult - 8);
> 	} else if (mult > 5) {
